import XCTest

final class MuteTests: XCTestCase {
    let out = "/private/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/muteuitest/"
    let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

    func dump(_ name: String) {
        try? app.debugDescription.write(toFile: out + name + ".txt", atomically: true, encoding: .utf8)
    }

    func testSearch() throws {
        app.launch()
        sleep(3)
        let searchTab = app.buttons["Search"].firstMatch
        XCTAssertTrue(searchTab.waitForExistence(timeout: 15))
        searchTab.tap()
        sleep(2)
        dump("search_tab")
        let field = app.textFields.firstMatch
        XCTAssertTrue(field.waitForExistence(timeout: 10))
        field.tap()
        field.typeText("loudspammer.test\n")
        sleep(3)
        dump("search_results")
        XCUIScreen.main.screenshot()
    }
}
EOF
xcodebuild test -project MuteUITest.xcodeproj -scheme MuteUITests -destination 'platform=iOS Simulator,id=5373A0B1-245F-40AC-928C-05D024236E44' -only-testing:MuteUITests/MuteTests/testSearch > run.log 2>&1; echo exit=$?; grep -E "error|failed|TEST" run.log | head -20; ls *.txt", "timeout": 900000}
